INCUMBENT_SHA256 = 'eeeced020b79edec2e578d56cb116e4aacddf4152d0baf710f5004f1d182cc06'
CUDA_SHA256 = '0caaad987b0cec9f59b67151362008a72c344e39bfd5e0a7ba5264c7f83d538d'

CASES = (
    (16, "MID", 2826848645790183780),
    (32, "MAIN", 2826933919152867123),
    (128, "MAIN", 2827104465878233812),
    (256, "MAIN", 2827189739240917158),
)
BUDGET_S = 230.0
POLL_S = 2.0
T0 = 0.0
_RAN = False
_LOG_BYTES = 0
_LOG_LIMIT = False


def log(text):
    global _LOG_BYTES, _LOG_LIMIT
    size = len((text + "\n").encode())
    if _LOG_BYTES + size > 9400 and not text.startswith("ZD_DONE"):
        if not _LOG_LIMIT:
            print("ZD_ERR log_budget_reached", flush=True)
            _LOG_LIMIT = True
        return
    _LOG_BYTES += size
    print(text, flush=True)


def error(where, exc):
    # Bound failure output too: compiler exceptions can contain megabytes.
    log(f"ZD_ERR {where} {type(exc).__name__}: {str(exc)[-140:]!r}")


def over():
    return time.monotonic() - T0 >= BUDGET_S


def incumbent_namespace():
    raw = zlib.decompress(base64.b85decode(INCUMBENT_B85))
    assert hashlib.sha256(raw).hexdigest() == INCUMBENT_SHA256
    ns = {"__name__": "_zerodiag_incumbent"}
    exec(compile(raw, "<embedded moe_b13.py>", "exec"), ns)
    assert hashlib.sha256(ns["CUDA_SRC"].encode()).hexdigest() == CUDA_SHA256
    return ns


def generate_weights(dev):
    """reference.generate_weights + nvfp4.random_weights, only local experts."""
    gen = torch.Generator(device=dev).manual_seed(5252)
    def random_weights(rows):
        q = torch.randint(0, 256, (32, rows, 2048), dtype=torch.uint8, generator=gen, device=dev)
        z = torch.randn((32, rows, 256), generator=gen, device=dev)
        sf = torch.exp2(7.0 + 0.4 * z).clamp(8.0, 448.0).to(torch.float8_e4m3fn)
        mean_sq = 4.0 ** 7.0 * math.exp(2 * (math.log(2) * 0.4) ** 2)
        gs = torch.tensor(1.0 / (8.6 * mean_sq * 4096) ** 0.5, dtype=torch.float32, device=dev)
        return q, sf, gs.expand(32).contiguous()
    a, sa, ga = random_weights(8192)
    b, sb, gb = random_weights(4096)
    return dict(w13=a, w13_sf=sa, w13_gs=ga, w2=b, w2_sf=sb, w2_gs=gb,
                post_norm_w=(0.1 * torch.randn((4096,), generator=gen, device=dev)).to(torch.bfloat16))


def generate_input(bs, dist, seed, dev):
    # Reproduction of reference.py:generate_input, including RNG draw order.
    gen = torch.Generator(device=dev).manual_seed(seed)
    x = torch.randn((bs, 4096), generator=gen, device=dev).to(torch.bfloat16)
    scores = torch.rand((bs, 256), generator=gen, device=dev)
    if dist == "normal":
        z = torch.randn((256,), generator=gen, device=dev)
        u = torch.rand((256,), generator=gen, device=dev).clamp(min=1e-12)
        scores = scores + 0.03 * z / (-u.log()).sqrt()
    else:
        raise ValueError(dist)
    routed = scores.topk(8, dim=-1)
    ids = routed.indices
    pairs = torch.bincount((ids // 32).flatten(), minlength=8)
    ids = (ids - 32 * pairs.argmax()) % 256
    return {"hidden_states": x, "topk_ids": ids.to(torch.int32).contiguous(),
            "topk_weights": (routed.values / routed.values.sum(-1, keepdim=True)).float().contiguous(),
            "config": {"bs": bs, "d_hidden": 4096, "d_expert": 4096, "n_experts": 256,
                       "local_start": 0, "local_count": 32, "top_k": 8, "sharding": "ep8"}}


def local_counts(ids):
    counts = [0] * 32
    for row in ids:
        for v in row:
            if 0 <= v < 32:
                counts[v] += 1
    return counts


def jobs_from_counts(counts, kind):
    """Same job order as route(): fat (>8), then skinny; MID splits all by 8."""
    if kind == "MID":
        return [(e, min(8, c - q)) for e, c in enumerate(counts) for q in range(0, c, 8)]
    fat = [(e, min(64, c - q)) for e, c in enumerate(counts) if c > 8 for q in range(0, c, 64)]
    return fat + [(e, c) for e, c in enumerate(counts) if 0 < c <= 8]


def compile_unit(ns, kind):
    """One thin-host CUDA TU; exact incumbent math/flags, unique linkage."""
    defs = tuple(ns[kind + "_DEFINES"]) + ("-DOKC_PRMTSC=1", "-DOKC_DQ7=1")
    src = ns["CUDA_SRC"]
    flags_as_source = "\n".join("#define " + d[2:].replace("=", " ", 1) for d in defs) + "\n"
    code = flags_as_source + src
    # torch/extension.h drags Python/pybind into every CUDA TU. Only this
    # equivalent Tensor alias is needed by the unchanged C++ launcher ABI.
    old = "#include <torch/extension.h>"
    assert code.count(old) == 1
    code = code.replace(old, "#include <ATen/ATen.h>\n#include <vector>\nnamespace torch { using Tensor = at::Tensor; }")
    stem = "zd_" + kind
    code = code.replace("namespace okc {", "namespace " + stem + " {").replace("okc::", stem + "::")
    renames = {"okc_run": stem + "_run", "okc_set_pdl": stem + "_set_pdl"}
    for old, new in renames.items():
        code = code.replace(old + "(", new + "(")
    return code, renames


def build_kind(ns, kind):
    """One C++ binding + one CUDA TU per build."""
    from pathlib import Path
    from torch.utils.cpp_extension import load, _get_build_directory
    code, rename = compile_unit(ns, kind)
    decl = ns["CPP_SRC"].replace("#include <torch/extension.h>", "")
    for old, new in rename.items():
        decl = decl.replace(old + "(", new + "(")
    cpp = ('#include <torch/extension.h>\n' + decl
           + '\nPYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {\n'
           + f'  m.def("okc_run", &{rename["okc_run"]});\n}}\n')
    tag = hashlib.sha256((cpp + code).encode()).hexdigest()[:16]
    name = "zerodiag_v1_" + kind.lower() + "_" + tag
    directory = Path(_get_build_directory(name, verbose=False))
    cppfile = directory / "binding.cpp"
    cppfile.write_text(cpp)
    cufile = directory / (kind.lower() + ".cu")
    cufile.write_text(code)
    return load(name=name, sources=[str(cppfile), str(cufile)], build_directory=str(directory),
                extra_cuda_cflags=["-O3", "-gencode=arch=compute_90a,code=sm_90a", "-lineinfo",
                                   "-DOKC_NS=3", "-DOKC_NSF=3"], verbose=False)


def timed(fn, flush):
    """READ L2 flush (amax over 256 MiB), then fn() between timing events.
    Host polls the end event; returns (ms, result) or (None, result) on timeout."""
    _FS.append(torch.amax(flush))
    s = torch.cuda.Event(enable_timing=True)
    e = torch.cuda.Event(enable_timing=True)
    s.record()
    res = fn()
    e.record()
    t = time.monotonic()
    while not e.query():
        if time.monotonic() - t > POLL_S:
            return None, res
        time.sleep(0.001)
    return s.elapsed_time(e), res


def scratch_report(ns, state):
    """Counters of the persistent scratch (call only after the launch completed)."""
    ib = state["scratch"][0]
    jmax, emax, hd = ns["JMAX"], ns["EMAX"], ns["HIDDEN"]
    ctr = ib[:8].tolist()
    da = int((ib[8:8 + jmax] != 0).sum().item())
    xr = int((ib[8 + 512:8 + 512 + jmax] != 0).sum().item())
    off = emax + emax * hd + 2 * ns["WGS_SLOTS"] * 4 * ns["WGS_FIXW"] + 2 * ns["WGS_SLOTS"] * 4
    das = int((state["scratch"][1][off:off + jmax * 16].view(torch.int32) != 0).sum().item())
    return f"ctr={'/'.join(str(v) for v in ctr[:6])} dA={da} xr={xr} dAs={das}"


class Dead(Exception):
    pass


def run_case(ns, state, fn, M, kind, seed, flush, dev):
    data = generate_input(M, "normal", seed, dev)
    mix_ids, mix_w = data["topk_ids"].clone(), data["topk_weights"].clone()
    ctr = torch.arange(M, device=dev)[:, None] * 8 + torch.arange(8, device=dev)[None, :]
    rem_ids = (32 + ctr % 224).to(torch.int32).contiguous()
    rem_w = torch.full((M, 8), 0.125, dtype=torch.float32, device=dev)
    counts = local_counts(mix_ids.cpu().tolist())
    log(f"ZD_CASE M={M} build={kind} routes={sum(counts)} jobs={len(jobs_from_counts(counts, kind))} "
        f"experts={sum(c > 0 for c in counts)} rem_ids_distinct_in_token="
        f"{int(all(len(set(r)) == 8 for r in rem_ids.cpu().tolist()))} rem_local={int(((rem_ids >= 0) & (rem_ids < 32)).any().item())}")
    for t in state["scratch"]:
        t.zero_()
    torch.cuda.synchronize()

    def stats(step, ms, out, ref, extra=""):
        a = out.float()
        finite = int(bool(torch.isfinite(a).all().item()))
        zero = int(bool((out == 0).all().item()))
        eq = "na" if ref is None else int(torch.equal(out.contiguous().view(torch.int16), ref.contiguous().view(torch.int16)))
        log(f"ZD M={M} build={kind} step={step} done=1 ms={ms:.3f} finite={finite} zero={zero} eq_mixed={eq}{extra} "
            + scratch_report(ns, state))

    def poll(step, run):
        ms, res = timed(run, flush)
        if ms is None:
            log(f"ZD_HANG M={M} build={kind} step={step} timeout_s={POLL_S}")
            raise Dead()
        return ms, res

    # eager warm (lazy module load, cudaFuncSetAttribute) then mixed1
    _, warm = poll("warm", lambda: fn(data, state))
    warm = warm.clone()
    ms, out = poll("mixed1", lambda: fn(data, state))
    ref = out.clone()
    stats("mixed1", ms, out, warm, extra=f" eq_warm={int(torch.equal(ref.view(torch.int16), warm.view(torch.int16)))}")
    # one graph on the MIXED inputs
    g = torch.cuda.CUDAGraph()
    held = []
    try:
        with torch.cuda.graph(g):
            held.append(fn(data, state))
        torch.cuda.synchronize()
    except Exception as exc:
        error(f"capture M={M}", exc)
        g = None
    gout = held[0] if held else None
    if g is not None:
        ms, _ = poll("mixed1_graph", lambda: g.replay())
        stats("mixed1_graph", ms, gout, ref)
        g1 = gout.clone()
        data["topk_ids"].copy_(rem_ids)
        data["topk_weights"].copy_(rem_w)
        ms, _ = poll("allremote_graph", lambda: g.replay())
        stats("allremote_graph", ms, gout, None)
        data["topk_ids"].copy_(mix_ids)
        data["topk_weights"].copy_(mix_w)
        ms, _ = poll("mixed2_graph", lambda: g.replay())
        stats("mixed2_graph", ms, gout, ref,
              extra=f" eq_g1={int(torch.equal(gout.view(torch.int16), g1.view(torch.int16)))}")
        del g, held, gout, g1
        torch.cuda.synchronize()
    rdata = dict(data, topk_ids=rem_ids.clone(), topk_weights=rem_w.clone())
    ms, out = poll("allremote_eager", lambda: fn(rdata, state))
    stats("allremote_eager", ms, out, None)


def run_all():
    dev = torch.device("cuda")
    if torch.cuda.get_device_capability(dev) != (9, 0):
        raise RuntimeError("Hopper required")
    ns = incumbent_namespace()
    os.environ["TORCH_CUDA_ARCH_LIST"] = "9.0a"
    os.environ["MAX_JOBS"] = "2"
    log(f"ZD_INFO v=1 device={torch.cuda.get_device_name(dev)!r} src=moe_b15_J0FIX sha={INCUMBENT_SHA256[:12]} "
        f"cuda={CUDA_SHA256[:12]} poll_s={POLL_S} flush_MiB=256")
    ready = queue.Queue()

    def worker(kind):
        start = time.monotonic()
        try:
            ready.put((kind, build_kind(ns, kind), None, time.monotonic() - start))
        except Exception as e:
            ready.put((kind, None, e, time.monotonic() - start))
    for kind in ("MAIN", "MID"):
        threading.Thread(target=worker, args=(kind,), daemon=True).start()
    raw = generate_weights(dev)
    ns["_ext"] = lambda defines=None: None
    state = ns.get("_moe_sel_original_prepare", ns["prepare"])(raw)
    del raw
    ns.get("_MOE_SEL", {}).clear()
    assert state["sfx"] == ("-DOKC_PRMTSC=1",)
    flush = torch.zeros(256 << 20, dtype=torch.uint8, device=dev)
    bundles, secs = {}, {}

    def get_bundle(kind):
        while kind not in bundles:
            try:
                k, mod, exc, sec = ready.get(timeout=max(.001, BUDGET_S - (time.monotonic() - T0)))
            except queue.Empty:
                log(f"ZD_ERR build budget_not_ready kind={kind}")
                return None
            secs[k] = sec
            if exc is not None:
                error(f"build {k}", exc)
                bundles[k] = None
            else:
                bundles[k] = mod
                log(f"ZD_BUILD kind={k} seconds={sec:.1f}")
        return bundles[kind]

    log(f"ZD_SETUP seconds={time.monotonic() - T0:.1f}")
    calls = {}

    def call_for(kind):
        if kind not in calls:
            bundle = get_bundle(kind)
            if bundle is None:
                calls[kind] = None
            else:
                ext = types.SimpleNamespace(okc_run=bundle.okc_run)
                callns = dict(ns)
                expected = tuple(ns[kind + "_DEFINES"]) + state["sfx"]

                def selected(defines=None, ext=ext, expected=expected):
                    assert tuple(defines) == expected, (defines, expected)
                    return ext
                callns["_ext"] = selected
                calls[kind] = types.FunctionType(ns["kernel_fn"].__code__, callns)
        return calls[kind]

    # MAIN first (the risky builds), MID (M=16) control last
    for M, kind, seed in sorted(CASES, key=lambda c: c[1] != "MAIN"):
        if over():
            log(f"ZD_ERR M={M} build={kind} budget_skip")
            continue
        fn = call_for(kind)
        if fn is None:
            continue
        try:
            run_case(ns, state, fn, M, kind, seed, flush, dev)
        except Dead:
            log("ZD_STOP hang: no further GPU work")
            return
        except Exception as exc:
            error(f"case M={M} build={kind}", exc)
            return  # a failed launch may leave the context unusable


def prepare(weights):
    global T0, _RAN
    if _RAN:
        return weights
    _RAN = True
    T0 = time.monotonic()
    try:
        run_all()
    except Exception as exc:
        error("prepare", exc)
    log(f"ZD_DONE seconds={time.monotonic() - T0:.1f}")
    return weights


def kernel_fn(data, weights):
    """Prefill-shaped zeros: deliberately fails correctness, never submit."""
    t = data["config"]["tokens"]
    dev = data["stream"].device
    return (torch.zeros((t, 8192), dtype=torch.bfloat16, device=dev),
            torch.zeros((t, 8192), dtype=torch.float32, device=dev),
            torch.zeros((t, 8), dtype=torch.int32, device=dev))
